    "SustainabilityClaim": [
      {
        "properties": {
          "_node_key": "51e170b44f703c4a",
          "claim_id": "patagonia_doc6_product_harm_reduction",
          "date": "2023",
          "description": "Patagonia endeavors to build the best products, while causing no unnecessary harm to the planet or its inhabitants by: 1) Designing and fabricating the highest quality products as defined by durability, multifunctionalism and non-obsolescence; 2) designing and fabricating products that are easily repaired and made from materials that can be reused or recycled; 3) designing and fabricating products with minimal impacts throughout the supply chain—including resource extraction, manufacturing and transportation—on water use, water quality, energy use, greenhouse gas emissions, chemical use, toxicity and waste; and 4) partnering with customers to take mutual responsibility for the life cycle of our products, including their repair, reuse and recycling.",
          "source": "doc page 6"
        },
        "connections": [
